{"action":"write_file","path":"ini.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parseIni } = require('./ini');

const plain = (o) => JSON.parse(JSON.stringify(o));

test('top-level keys and a section', () => {
  const text = 'name = demo\n[server]\nhost = localhost\nport = 8080\n';
  assert.deepEqual(plain(parseIni(text)), { name: 'demo', server: { host: 'localhost', port: '8080' } });
});

test('comments and blank lines are ignored', () => {
  assert.deepEqual(plain(parseIni('; note\n\n# other\na = 1\n')), { a: '1' });
});

test('quotes and spaces', () => {
  const text = 'a = " hello "\nb = \nc = ""\nd = 1 ; not a comment\n';
  assert.deepEqual(plain(parseIni(text)), { a: ' hello ', b: '', c: '', d: '1 ; not a comment' });
});

test('merged sections', () => {
  const text = '[db]\nhost = localhost\n[db]\nport = 3306\n';
  assert.deepEqual(plain(parseIni(text)), { db: { host: 'localhost', port: '3306' } });
});

test('Object.create(null) prototype check', () => {
  const res = parseIni('a = 1\n[sec]\nb = 2\n');
  assert.equal(Object.getPrototypeOf(res), null);
  assert.equal(Object.getPrototypeOf(res.sec), null);
});

test('TypeError when not a string', () => {
  assert.throws(() => parseIni(123), TypeError);
});

test('SyntaxError with line number', () => {
  const lines = ['a = 1', 'invalid line', 'b = 2'];
  assert.throws(() => parseIni(lines.join('\n')), (err) => {
    return err instanceof SyntaxError && err.line === 2;
  });

  assert.throws(() => parseIni('[]'), (err) => {
    return err instanceof SyntaxError && err.line === 1;
  });

  assert.throws(() => parseIni('[unclosed'), (err) => {
    return err instanceof SyntaxError && err.line === 1;
  });

  assert.throws(() => parseIni('= val'), (err) => {
    return err instanceof SyntaxError && err.line === 1;
  });
});
"}
